package stage

import (
	"fmt"
	"io"
	"sort"
	"strconv"
	"strings"

	"example.com/flowctl/internal/record"
)

type PivotStage struct {
	index        []string
	columns      string
	values       string
	asType       string
	agg          string
	fill         string
	sortColumns  string
	columnPrefix string
	strictSchema bool
	dropEmpty    bool
	onConflict   string
}

type pivotCell struct {
	count     int
	sum       float64
	min       float64
	max       float64
	hasNum    bool
	first     string
	last      string
	hasStr    bool
	contribs  int
}

func (s *PivotStage) Apply(in []*record.Record, stderr io.Writer, strict bool, stats *Stats) ([]*record.Record, error) {
	order := []string{}
	rows := map[string]*pivotRow{}
	colOrder := []string{}
	cols := map[string]bool{}

	for _, r := range in {
		idxParts := make([]string, len(s.index))
		for i, col := range s.index {
			v, ok := r.Get(col)
			if !ok {
				v = ""
			}
			idxParts[i] = v
		}
		idxKey := strings.Join(idxParts, "\x00")

		col, ok := r.Get(s.columns)
		if !ok {
			col = ""
		}

		row, exists := rows[idxKey]
		if !exists {
			row = &pivotRow{
				idxParts: idxParts,
				cells:    map[string]*pivotCell{},
			}
			rows[idxKey] = row
			order = append(order, idxKey)
		}

		if !cols[col] {
			cols[col] = true
			colOrder = append(colOrder, col)
		}

		cell, exists := row.cells[col]
		if !exists {
			cell = &pivotCell{}
			row.cells[col] = cell
		}
		cell.contribs++

		switch s.agg {
		case "count":
			cell.count++
		case "sum", "min", "max", "avg":
			v, ok := r.Get(s.values)
			if !ok || v == "" {
				continue
			}
			f, err := parseFloat(v)
			if err != nil {
				return nil, fmt.Errorf("pivot: non-numeric value in column %s at row %d", s.values, r.InputRow)
			}
			cell.count++
			cell.sum += f
			if !cell.hasNum || f < cell.min {
				cell.min = f
			}
			if !cell.hasNum || f > cell.max {
				cell.max = f
			}
			cell.hasNum = true
		case "first", "last":
			v, ok := r.Get(s.values)
			if !ok {
				v = ""
			}
			if s.onConflict == "error" && cell.contribs > 1 {
				return nil, fmt.Errorf("pivot: duplicate contributor for cell %s/%s", strings.Join(row.idxParts, "|"), col)
			}
			if !cell.hasStr {
				cell.first = v
				cell.hasStr = true
			}
			cell.last = v
		}
	}

	sortedCols := s.sortPivotColumns(colOrder)

	out := make([]*record.Record, 0, len(order))
	for _, idxKey := range order {
		row := rows[idxKey]

		allEmpty := true
		for _, col := range sortedCols {
			cell := row.cells[col]
			if cell != nil && cell.contribs > 0 {
				allEmpty = false
				break
			}
		}
		if s.dropEmpty && allEmpty {
			continue
		}

		nr := record.New()
		nr.InputRow = 0
		for i, col := range s.index {
			nr.Set(col, row.idxParts[i])
		}

		for _, col := range sortedCols {
			name := s.columnPrefix + col
			cell := row.cells[col]
			val, hadContrib := s.finalizeCell(cell)
			if s.strictSchema && !hadContrib {
				return nil, fmt.Errorf("pivot: row %s missing pivot value %s", strings.Join(row.idxParts, "|"), col)
			}
			if !hadContrib {
				val = s.fill
			}
			nr.Set(name, val)
		}

		out = append(out, nr)
	}

	return out, nil
}

type pivotRow struct {
	idxParts []string
	cells    map[string]*pivotCell
}

func (s *PivotStage) finalizeCell(cell *pivotCell) (string, bool) {
	if cell == nil || cell.contribs == 0 {
		return "", false
	}
	switch s.agg {
	case "count":
		return strconv.Itoa(cell.count), true
	case "sum":
		if cell.count == 0 {
			return "", false
		}
		return formatFloat(cell.sum), true
	case "min":
		if cell.count == 0 {
			return "", false
		}
		return formatFloat(cell.min), true
	case "max":
		if cell.count == 0 {
			return "", false
		}
		return formatFloat(cell.max), true
	case "avg":
		if cell.count == 0 {
			return "", false
		}
		return formatFloat(cell.sum / float64(cell.count)), true
	case "first":
		return cell.first, true
	case "last":
		return cell.last, true
	}
	return "", false
}

func (s *PivotStage) sortPivotColumns(colOrder []string) []string {
	out := make([]string, len(colOrder))
	copy(out, colOrder)
	switch s.sortColumns {
	case "asc":
		sort.Slice(out, func(i, j int) bool { return out[i] < out[j] })
	case "desc":
		sort.Slice(out, func(i, j int) bool { return out[i] > out[j] })
	case "ingest":
	}
	return out
}

func buildPivot(idx int, sm map[string]interface{}) (Stage, error) {
	indexRaw, ok := sm["index"]
	if !ok {
		return nil, fmt.Errorf("config: pivot: index must be a non-empty list")
	}
	index, err := toStringList(indexRaw)
	if err != nil {
		return nil, fmt.Errorf("config: pivot: index %v", err)
	}
	if len(index) == 0 {
		return nil, fmt.Errorf("config: pivot: index must be a non-empty list")
	}
	for _, col := range index {
		if col == "" {
			return nil, fmt.Errorf("config: pivot: index must be a non-empty list")
		}
	}

	columns, ok := getString(sm, "columns")
	if !ok || columns == "" {
		return nil, fmt.Errorf("config: pivot: columns is required")
	}

	values, ok := getString(sm, "values")
	if !ok || values == "" {
		return nil, fmt.Errorf("config: pivot: values is required")
	}

	asType, ok := getString(sm, "as")
	if !ok || asType == "" {
		return nil, fmt.Errorf("config: pivot: as is required")
	}
	if asType != "string" && asType != "number" {
		return nil, fmt.Errorf("config: pivot: as must be string or number")
	}

	agg, ok := getString(sm, "agg")
	if !ok || agg == "" {
		return nil, fmt.Errorf("config: pivot: agg is required")
	}
	switch agg {
	case "sum", "min", "max", "avg", "count", "first", "last":
	default:
		return nil, fmt.Errorf("config: pivot: unknown agg %q", agg)
	}

	switch agg {
	case "sum", "min", "max", "avg":
		if asType != "number" {
			return nil, fmt.Errorf("config: pivot: agg %s requires as: number", agg)
		}
	case "first", "last":
		if asType != "string" {
			return nil, fmt.Errorf("config: pivot: agg %s requires as: string", agg)
		}
	}

	fill := ""
	if f, ok := getString(sm, "fill"); ok {
		fill = f
	}

	sortColumns := "asc"
	if sc, ok := getString(sm, "sort_columns"); ok {
		if sc == "" {
			return nil, fmt.Errorf("config: pivot: sort_columns must be asc, desc, or ingest")
		}
		sortColumns = sc
	}
	switch sortColumns {
	case "asc", "desc", "ingest":
	default:
		return nil, fmt.Errorf("config: pivot: sort_columns must be asc, desc, or ingest")
	}

	columnPrefix := ""
	if cp, ok := getString(sm, "column_prefix"); ok {
		columnPrefix = cp
	}

	strictSchema := false
	if b, ok, err := getBool(sm, "strict_schema"); ok {
		if err != nil {
			return nil, fmt.Errorf("config: pivot: strict_schema must be a boolean")
		}
		strictSchema = b
	}

	dropEmpty := false
	if b, ok, err := getBool(sm, "drop_empty"); ok {
		if err != nil {
			return nil, fmt.Errorf("config: pivot: drop_empty must be a boolean")
		}
		dropEmpty = b
	}

	onConflict := "error"
	if oc, ok := getString(sm, "on_conflict"); ok {
		if oc == "" {
			return nil, fmt.Errorf("config: pivot: on_conflict must be error, keep_first, or keep_last")
		}
		onConflict = oc
	}
	switch onConflict {
	case "error", "keep_first", "keep_last":
	default:
		return nil, fmt.Errorf("config: pivot: on_conflict must be error, keep_first, or keep_last")
	}

	if agg != "first" && agg != "last" && onConflict != "error" {
		return nil, fmt.Errorf("config: pivot: on_conflict only valid with agg: first or agg: last")
	}
	if agg == "first" && onConflict == "keep_last" {
		return nil, fmt.Errorf("config: pivot: on_conflict keep_last is invalid with agg: first")
	}
	if agg == "last" && onConflict == "keep_first" {
		return nil, fmt.Errorf("config: pivot: on_conflict keep_first is invalid with agg: last")
	}

	known := map[string]bool{
		"type":          true,
		"index":         true,
		"columns":       true,
		"values":        true,
		"as":            true,
		"agg":           true,
		"fill":          true,
		"sort_columns":  true,
		"column_prefix": true,
		"strict_schema": true,
		"drop_empty":    true,
		"on_conflict":   true,
	}
	for k := range sm {
		if !known[k] {
			return nil, fmt.Errorf("config: pivot: unknown field %q", k)
		}
	}

	return &PivotStage{
		index:        index,
		columns:      columns,
		values:       values,
		asType:       asType,
		agg:          agg,
		fill:         fill,
		sortColumns:  sortColumns,
		columnPrefix: columnPrefix,
		strictSchema: strictSchema,
		dropEmpty:    dropEmpty,
		onConflict:   onConflict,
	}, nil
}
